        {
            navigationService.clearNavigation();
            activeLocation = null;
            resetAllRowColors();
            log.debug("Cleared navigation for {}", locationName);
            return;
        }

        navigationService.navigateTo(coords);
        activeLocation = locationName;
        tileNoteService.updateForTask(currentMonsterName);

