            position = 7,
            hidden = true
    )
    default boolean showReminderOverlay()
    {
        return true;
    }

    @ConfigItem(keyName = "showReminderOverlay", name = "", description = "")
    void setShowReminderOverlay(boolean value);

    @ConfigItem(
            keyName = "streakOptimizerEnabled",
            name = "Streak Point Optimizer",
